const obGroups=[['all','Tout'],['pregnancy','Grossesse'],['birth','Naissance'],['postpartum','Suites de couches']];
let obstetricGroup='all';
function currentObstetric(){return activeRouteKind==='surgery'?null:obstetricRoutes[currentFlow];}
function obstetricProfile(){return currentObstetric()?.profiles.find(p=>p.id===answers.obProfile);}
function obstetricDanger(){return Boolean(currentObstetric()&&(currentObstetric().critical||obstetricProfile()?.urgent||careProductBlocked()||['not_breathing','unconscious_breathing','confused','unknown'].includes(answers.conscious)||['weak','no','unknown'].includes(answers.obBaby)));}
function obstetricCareStep(step){
 if(step.dynamicObPriority)return {...step,dynamicConscious:false,do:['Interrompre le soin non prioritaire ; vérifier les réactions et le souffle, puis demander une aide obstétricale urgente.','Préserver l’intimité et la chaleur ; ne pas forcer de boisson, ne rien administrer automatiquement.','Noter la réévaluation effectivement constatée ; un réveil ne prouve pas que la cause est résolue.'],say:['« Restez auprès d’elle ; surveillez sa respiration pendant que nous faisons venir de l’aide. »'],care:{material:['Couverture','Linge propre']}};
 if(!step.dynamicObCare)return step;
 const route=currentObstetric(),profile=obstetricProfile();
 const systemic=careProductBlocked();
 let actions=profile?[...profile.actions]:['Préciser les observations avant de choisir un soin.'];
 if(systemic)actions=['Donner la priorité aux réactions, au souffle et aux pertes ; poursuivre la prise en charge urgente.','Suspendre les gestes non prioritaires et demander une aide obstétricale.','Aucun produit automatique et aucune boisson forcée ; surveiller sans garantir une récupération.'];
 if(route.birth){
  if(answers.obBaby==='breathing')actions.push('Enfant né et respiration constatée : préparer linge sec, chaleur douce et surveillance dédiée ; contrôler aussi la mère.');
  else if(['weak','no'].includes(answers.obBaby))actions=['Confier immédiatement la prise en charge respiratoire du nouveau-né à une aide dédiée, sans geste violent ni produit stimulant.','Garder un assistant auprès de la mère et surveiller ses pertes et réactions.','La reprise respiratoire n’est jamais déduite du passage à l’étape suivante.'];
  else if(answers.obBaby==='unknown')actions.push('État du nouveau-né non évalué : l’examiner en priorité, sans annoncer une naissance sans complication.');
 }
 return {...step,do:actions,say:systemic?['« Votre état passe avant la suite. Nous restons auprès de vous. »']:[route.question,'« Je vous explique ce qui a été constaté et ce que nous préparons. »'],confirmActs:systemic?[]:profile?.confirm||[],care:{material:['Savon et eau propre pour les mains','Linge propre','Couverture',...(route.birth?['Linge sec distinct pour le nouveau-né']:[])]}};
}
function obstetricRoutineActs(step){
 if(step.dynamicObPriority)return ['watch','Renfort obstétrical demandé'];
 const profile=obstetricProfile(),systemic=careProductBlocked();
 const acts=systemic?['Surveillance maternelle prioritaire','Renfort obstétrical demandé']:profile?.care||[];
 if(currentObstetric()?.birth&&answers.obBaby==='breathing')return [...acts,'Linge sec, chaleur douce et surveillance du nouveau-né'];
 if(currentObstetric()?.birth&&['weak','no','unknown'].includes(answers.obBaby))return ['Surveillance maternelle','Prise en charge urgente du nouveau-né organisée'];
 return [...acts];
}
for(const [id,route]of Object.entries(obstetricRoutes)){
 flows[id]={title:route.title,obstetric:true,urgency:route.critical?'critical':'serious',steps:[
  {title:'État de la patiente',do:['Observer les réactions, le souffle et un saignement important avant le récit détaillé.'],say:['« Vous m’entendez ? Je vais d’abord vérifier votre état. »'],choices:flows.gunshot.steps[0].choices.map(c=>({label:c.label.replace('Conscient','Consciente').replace('Confus','Confuse').replace('Inconscient','Inconsciente'),set:{...c.set}}))},
  {title:'Priorités obstétricales',dynamicConscious:true,dynamicObPriority:true},
  {title:'Ce qui est constaté',do:route.observe,say:[route.question],choices:[...route.profiles.map(p=>({label:p.label,set:{obProfile:p.id}})),{label:'Impossible à évaluer pour le moment',set:{obProfile:'unknown'}}]},
  ...(route.birth?[{title:'Naissance et état de l’enfant constatés',do:['Indiquer seulement la situation effectivement observée ; ce choix ne déclenche pas une naissance.'],say:['« L’enfant est-il né ? Qui reste auprès de lui pour observer son souffle ? »'],choices:[{label:'Enfant pas encore né',set:{obBaby:'unborn'}},{label:'Enfant né, respiration constatée',set:{obBaby:'breathing'}},{label:'Enfant né, respiration faible / difficile',set:{obBaby:'weak'}},{label:'Enfant né, respiration non constatée',set:{obBaby:'no'}},{label:'Situation / respiration non encore évaluée',set:{obBaby:'unknown'}}]}]:[]),
  {title:'Prise en charge et consignes',dynamicObCare:true,do:[],say:[]}
 ]};
 careMemoRows[id]=['Réactions · souffle · pertes · '+(route.birth?'mère et enfant':'évolution'),'Expliquer, préserver l’intimité, observer puis adapter les soins','Savon · eau propre · linge ; produits d’époque sur décision distincte','Sang abondant · malaise · souffle difficile · fièvre / aggravation'];
 sceneEndings[id]=['Reprendre les observations réellement constatées, sans issue imposée.',route.question,'Repos, surveillance et contrôle convenus suivant la situation.','Sang abondant, malaise, souffle difficile, fièvre ou aggravation.'];
 interventionMaterials[id]=['Savon','Eau propre','Linge propre','Couverture'];
}
function showObstetrics(){show('obstetrics');renderObstetricCatalog();}
function setObstetricGroup(group){if(!obGroups.some(([key])=>key===group))return;obstetricGroup=group;renderObstetricCatalog();}
function obReferencesMarkup(){return `<details class="ob-references"><summary>Matériel, produits et vocabulaire de 1889</summary><p>Repères d’époque, variables selon la formation et les moyens. Aucun dosage ni préparation. Manuel d’Effie, section III ; les sources modernes servent seulement à éviter de banaliser les signes graves.</p><div class="ob-reference-grid">${[
 ['Hygiène / antisepsie','Savon, eau propre, linge et matériel préparés. L’hygiène est centrale ; un antiseptique externe n’est pas une douche interne et ne guérit pas une fièvre puerpérale.',obSources.book],
 ['Stéthoscope obstétrical','Cornet d’auscultation fœtale, documenté au XIXe siècle. Son utilisation dépend du terme ; une écoute incertaine ne permet pas d’annoncer l’issue de la grossesse.',obSources.stethoscope],
 ['Forceps obstétrical','Instrument d’assistance à la naissance, distinct de la pince à projectile. Mentionner l’acte décidé et ses suites, sans placement ni manœuvre détaillés.',obSources.bag],
 ['Éther / chloroforme','Liquides volatils employés pour l’anesthésie au XIXe siècle. Choix distinct d’une simple douleur, nécessitant une surveillance dédiée ; aucune inhalation automatique.',obSources.anaesthesia],
 ['Ergot de seigle','Préparation historique mentionnée dans le manuel après accouchement. Produit toxique, pas un remède pour toute perte de sang ni un moyen automatique de déclencher le travail.',obSources.bag],
 ['Opium / laudanum','Préparations opiacées historiques. Sédation et effets sur la respiration possibles ; ne pas les ajouter automatiquement à la mère ou au nourrisson.',obSources.bag],
 ['Délivrance / lochies','Délivrance : expulsion du placenta après la naissance. Lochies : pertes des suites de couches. Ni expulsion ni diminution du sang ne sont déduites d’un clic.',obSources.book],
 ['Fièvre puerpérale','Terme d’époque pour les fièvres des suites de couches. Rechercher le foyer et l’aggravation ; pas d’antibiotique moderne, d’échographie ou de résultat garanti dans une scène de 1889.',obSources.book]
 ].map(([title,text,url])=>`<article><h4>${title}</h4><p>${text}</p><a href="${url}" target="_blank" rel="noopener noreferrer">Repère historique</a></article>`).join('')}</div><p><a href="${obSources.safety}" target="_blank" rel="noopener noreferrer">Signes graves : repère actuel de sécurité, pas un protocole de 1889</a></p></details>`;}
function renderObstetricCatalog(){
 const ids=Object.keys(obstetricRoutes).sort((a,b)=>routeTitleCompare(obstetricRoutes[a].title,obstetricRoutes[b].title));
 document.getElementById('obstetrics').innerHTML=`<div class="topbar"><div><h2>Obstétrique</h2><p class="muted">Grossesse, naissance et suites de couches · repères de scène pour 1889.</p></div><button class="secondary" onclick="goHome()">Accueil</button></div><div class="ob-catalog-tools"><div class="ob-filters" role="group" aria-label="Période obstétricale">${obGroups.map(([key,title])=>`<button type="button" class="secondary" aria-pressed="${obstetricGroup===key}" onclick="setObstetricGroup('${key}')">${title}</button>`).join('')}</div><button class="secondary" onclick="showObstetricFollowup()">Suivis obstétricaux</button></div><div class="case-grid ob-case-grid">${ids.filter(id=>obstetricGroup==='all'||obstetricRoutes[id].group===obstetricGroup).map(id=>{const r=obstetricRoutes[id];return `<button type="button" class="case" onclick="start('${id}')"><strong>${emojiIcon(r.icon)} ${reportEscape(r.title)}</strong><span class="muted">${reportEscape(r.intro)}</span></button>`;}).join('')}</div>${obReferencesMarkup()}`;
}
function showObstetricFollowup(){showFollowup();filterFollowup('obstetrics');}
function registerObstetricFollowups(){
 for(const [id,r]of Object.entries(obstetricRoutes)){
  if(followupMenuKeys.includes(id))continue;
  followupTypes[id]={title:r.title,sourceFlow:id,group:'obstetrics',intro:'Reprendre les suites : '+r.intro,checks:['Reprendre le motif, les gestes reçus et la situation de grossesse ou de naissance rapportée.','Comparer douleur, pertes, fièvre, fatigue, réactions et souffle ; préserver l’intimité.','Un signe nouveau ou aggravé demande une nouvelle évaluation, pas une guérison supposée.'],signs:['Amélioration rapportée','Gêne persistante','Aggravation rapportée','Pertes diminuées','Saignement repris','Fièvre rapportée','Malaise rapporté','Gêne respiratoire','Douleur aggravée'],care:['Évolution obstétricale réévaluée','Soins reçus revérifiés','Hygiène et confort réévalués','Consignes réexpliquées','Examen obstétrical urgent organisé','Nouveau contrôle convenu']};
  followupMenuKeys.push(id);
  flows['followup_'+id]={title:'Suivi : '+r.title,followup:id,obstetric:true,urgency:'serious',steps:[{title:'Évolution constatée',dynamicFollowup:'findings'},{title:'Soins effectués et consignes',dynamicFollowup:'care'}]};
 }
}
